"""Jailed asset storage service."""

import os
from errors import SecurityBoundaryError
from sanitizer import PathSanitizer


class JailedFileStore:
    def __init__(self, base_directory: str):
        self.base_dir = os.path.abspath(base_directory)
        self.sanitizer = PathSanitizer(self.base_dir)
        self._virtual_fs: dict[str, str] = {}

    def write_virtual(self, relative_path: str, data: str) -> str:
        safe_target = self.sanitizer.resolve_safe_path(relative_path)
        self._virtual_fs[safe_target] = data
        return safe_target

    def read_virtual(self, relative_path: str) -> str:
        safe_target = self.sanitizer.resolve_safe_path(relative_path)
        if safe_target not in self._virtual_fs:
            raise FileNotFoundError(f"Asset not found: {relative_path}")
        return self._virtual_fs[safe_target]

reference_fix.sanitizer.py:
"""File path sanitization and canonicalization routines."""

import os
import urllib.parse
from errors import SecurityBoundaryError


class PathSanitizer:
    def __init__(self, root_dir: str):
        self.root_dir = os.path.abspath(root_dir)

    def resolve_safe_path(self, user_path: str) -> str:
        curr = user_path
        for _ in range(3):
            decoded = urllib.parse.unquote(curr)
            if decoded == curr:
                break
            curr = decoded

        clean = curr.replace("\x00", "").replace("\\", "/")
        segments = [s for s in clean.split("/") if s and s != "."]
        resolved: list[str] = []
        for seg in segments:
            if seg == ".." or seg.startswith("..") or ".." in seg:
                raise SecurityBoundaryError(f"Path traversal detected: {user_path}")
            resolved.append(seg)

        target = os.path.abspath(os.path.join(self.root_dir, *resolved))
        if not target.startswith(self.root_dir):
            raise SecurityBoundaryError(f"Path traversal detected: {user_path}")
        return target
